local quests = ns.ForeverQuestData.quests
ns.ForeverSwept = {}   -- (rows that are only part of one: QuestData.lua's Mixed)
for id, row in pairs(rows) do
    if not quests[id] then
        quests[id] = row
        ns.ForeverSwept[id] = true
    end
end

