local byHand = ns.ForeverQuestData.fix or {}
ns.ForeverQuestData.fix = byHand
for id, fields in pairs(fix) do
    local row = byHand[id] or {}
    for i, v in pairs(fields) do
        if row[i] == nil then row[i] = v end
    end
    byHand[id] = row
end
